const INPUT_NODE = 'When Executed by Another Workflow';

function folderName(directory) {
  return String(directory ?? '').split('/').filter(Boolean).pop() ?? '';
}

function parseConfig(entry) {
  let config;
  try {
    config = JSON.parse(entry.text);
  } catch {
    return null;
  }
  return config !== null && typeof config === 'object' && config.id === entry.folder ? config : null;
}

function selectClient(entries, phoneNumberId) {
  const invalidConfigs = [];
  if (typeof phoneNumberId !== 'string' || phoneNumberId.trim() === '') {
    return { found: false, reason: 'invalid_input', invalidConfigs };
  }
  const matches = [];
  for (const entry of entries) {
    if (entry.folder === '' || entry.folder.startsWith('_')) continue;
    const config = parseConfig(entry);
    if (config === null) {
      invalidConfigs.push(entry.folder);
    } else if (config.active === true && config.whatsapp?.phoneNumberId === phoneNumberId) {
      matches.push(config);
    }
  }
  if (matches.length === 1) {
    return { found: true, config: matches[0], invalidConfigs };
  }
  if (matches.length > 1) {
    return { found: false, reason: 'duplicate', clientIds: matches.map((config) => config.id), invalidConfigs };
  }
  return { found: false, reason: 'not_found', invalidConfigs };
}

const phoneNumberId = $(INPUT_NODE).first().json.phoneNumberId;
const entries = [];
for (const [index, item] of $input.all().entries()) {
  if (!item.binary?.data) continue;
  const buffer = await this.helpers.getBinaryDataBuffer(index, 'data');
  entries.push({ folder: folderName(item.binary.data.directory), text: buffer.toString('utf8') });
}

return [{ json: selectClient(entries, phoneNumberId) }];
